@@ -1,1 +1,17 @@
+export function formatUser(u: User) {
+  const name = u.name.trim().toLowerCase();
+  if (name.length > 20) return name.slice(0, 17) + '...';
+  return name;
+}
+
+export function formatOrder(o: Order) {
+  const name = o.title.trim().toLowerCase();
+  if (name.length > 20) return name.slice(0, 17) + '...';
+  return name;
+}
